import random

def generate(seed):
    rng = random.Random(seed)

    # The problem is to count the number of valid 3x3 grids where no two adjacent cells have the same color.
    # This is equivalent to counting the number of valid 3-colorings of a 3x3 grid with the given constraints.

    # The number of valid colorings for a 3x3 grid with no two adjacent cells having the same color is 2^3 * 2^3 * 2^3 = 2^9 = 512.
    # This is because each cell can be colored independently, and the color of each cell is determined by the colors of its adjacent cells.

    answer = 2 ** 9

    # Independent route: generate all possible colorings and count the valid ones.
    check = 0
    for r1 in range(2):
        for r2 in range(2):
            for r3 in range(2):
                for b1 in range(2):
                    for b2 in range(2):
                        for b3 in range(2):
                            for g1 in range(2):
                                for g2 in range(2):
                                    for g3 in range(2):
                                        # Check if no two adjacent cells have the same color
                                        if (r1 != r2 and r1 != b1 and r1 != g1 and
                                            r2 != b2 and r2 != g2 and
                                            b1 != b2 and b1 != g1 and b1 != g2 and
                                            b2 != g2 and
                                            g1 != g2):
                                            check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        "Consider a 3x3 grid. Each cell can be colored either red, blue, or green. "
        "How many ways can the grid be colored such that no two adjacent cells (sharing a side) "
        "have the same color? State only the integer."
    )

    return problem, str(answer)


