import random
from math import comb, factorial

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(5, 15)
    k = rng.randint(2, n)
    m = rng.randint(2, n)

    # The number of ways to partition a set of n elements into k non-empty subsets
    # is given by the Stirling numbers of the second kind, S(n, k).
    # We need to ensure that no subset contains more than m elements.
    # This is a complex combinatorial problem, but we can use a recursive approach
    # to count the valid partitions.

    def count_partitions(n, k, m):
        if n == 0 and k == 0:
            return 1
        if n == 0 or k == 0:
            return 0
        if n < k:
            return 0
        if k == 1:
            return 1 if n <= m else 0
        return sum(count_partitions(n - i, k - 1, m) for i in range(1, min(n, m) + 1))

    answer = count_partitions(n, k, m)

    # Independent route: enumerate all possible partitions and count the valid ones
    check = 0
    for partition in partitions(n, k):
        if all(len(subset) <= m for subset in partition):
            check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a set of {n} distinct elements. How many ways can you partition this set into {k} non-empty subsets such that no subset contains more than {m} elements? State only the integer."
    )

    return problem, str(answer)

def partitions(n, k):
    if n == 0 and k == 0:
        yield []
    if n == 0 or k == 0:
        return
    if n < k:
        return
    if k == 1:
        yield [[i for i in range(n)]]
    for i in range(1, min(n, k) + 1):
        for p in partitions(n - i, k - 1):
            yield [p[0][:i]] + p[1:]


