import random

def generate(seed):
    rng = random.Random(seed)

    sum_of_squares = rng.randint(50, 100)

    # Find all pairs (x, y) such that x^2 + y^2 = sum_of_squares
    solutions = []
    for x in range(1, int(sum_of_squares**0.5) + 1):
        y_squared = sum_of_squares - x**2
        if y_squared >= 0:
            y = int(y_squared**0.5)
            if y**2 == y_squared:
                solutions.append((x, y))

    answer = len(solutions)

    # Independent route: brute force over the stated domain
    check = sum(
        1
        for x in range(1, int(sum_of_squares**0.5) + 1)
        for y in range(1, int(sum_of_squares**0.5) + 1)
        if x**2 + y**2 == sum_of_squares
    )

    assert answer == check, f"answer={answer} check={check}"

    problem = f"Let x and y be positive integers satisfying x^2 + y^2 = {sum_of_squares}. Find the number of solutions (x, y). State only the integer."
    return problem, str(answer)


