import random

def generate(seed):
    rng = random.Random(seed)
    vertex_count = rng.randint(3, 10)
    edge_count = rng.randint(0, vertex_count * (vertex_count - 1) // 2)

    # Generate a random graph with the given number of vertices and edges
    graph = {i: set() for i in range(vertex_count)}
    edges = set()
    while len(edges) < edge_count:
        u, v = rng.randint(0, vertex_count - 1), rng.randint(0, vertex_count - 1)
        if u != v and (u, v) not in edges and (v, u) not in edges:
            graph[u].add(v)
            graph[v].add(u)
            edges.add((u, v))

    # Compute the chromatic number using a greedy algorithm
    colors = [0] * vertex_count
    for i in range(vertex_count):
        available_colors = set(range(vertex_count))
        for j in graph[i]:
            if colors[j] in available_colors:
                available_colors.remove(colors[j])
        colors[i] = min(available_colors)

    answer = max(colors) + 1

    # Independent route: compute the chromatic number using a brute force approach
    def is_valid_coloring(coloring):
        for i in range(vertex_count):
            for j in graph[i]:
                if coloring[i] == coloring[j]:
                    return False
        return True

    def backtrack(vertex, coloring):
        if vertex == vertex_count:
            return True
        for color in range(answer):
            coloring[vertex] = color
            if is_valid_coloring(coloring):
                if backtrack(vertex + 1, coloring):
                    return True
        return False

    check = 0
    for coloring in range(2 ** (vertex_count * answer)):
        coloring = [int(x) for x in format(coloring, f'0{vertex_count * answer}b')]
        if is_valid_coloring(coloring):
            check = max(check, max(coloring) + 1)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let G be a graph with {vertex_count} vertices and {edge_count} edges. "
        f"Find the maximum number of colors that can be used to color the vertices "
        f"of G such that no two adjacent vertices share the same color. State only "
        f"the integer."
    )

    return problem, str(answer)


