import random
from itertools import product

def generate(seed):
    rng = random.Random(seed)
    grid_size = 4

    def is_valid_tiling(tiling):
        visited = set()
        for i, j in tiling:
            if (i, j) in visited:
                return False
            visited.add((i, j))
            if i < grid_size - 1 and (i + 1, j) in tiling:
                return False
            if j < grid_size - 1 and (i, j + 1) in tiling:
                return False
        return True

    def count_tilings():
        count = 0
        for tiling in product(range(grid_size), repeat=grid_size):
            if is_valid_tiling(tiling):
                count += 1
        return count

    answer = count_tilings()

    check = sum(
        1 for tiling in product(range(grid_size), repeat=grid_size)
        if is_valid_tiling(tiling)
    )
    assert answer == check, f"answer={answer} check={check}"

    problem = f"Consider a {grid_size}x{grid_size} grid. In how many ways can you tile the grid completely with 2x1 dominoes, where each domino covers exactly two adjacent squares? State only the integer."
    return problem, str(answer)


