import random
from itertools import product

def generate(seed):
    rng = random.Random(seed)

    grid_width = rng.randint(3, 10)
    grid_height = rng.randint(3, 10)
    pieces = rng.randint(1, grid_width * grid_height // 2)
    piece_shape = "L"  # Example piece shape, can be extended

    # Define the piece shape as a set of coordinates
    if piece_shape == "L":
        piece = {(0, 0), (0, 1), (1, 0), (1, 1)}
    else:
        raise ValueError("Unsupported piece shape")

    # Function to check if a piece can be placed at a given position
    def can_place(grid, x, y):
        for dx, dy in piece:
            if not (0 <= x + dx < grid_width and 0 <= y + dy < grid_height):
                return False
            if grid[x + dx][y + dy] == 1:
                return False
        return True

    # Function to place a piece at a given position
    def place_piece(grid, x, y):
        for dx, dy in piece:
            grid[x + dx][y + dy] = 1

    # Function to remove a piece from a given position
    def remove_piece(grid, x, y):
        for dx, dy in piece:
            grid[x + dx][y + dy] = 0

    # Initialize the grid
    grid = [[0 for _ in range(grid_height)] for _ in range(grid_width)]

    # Place pieces
    placed = 0
    while placed < pieces:
        x, y = rng.choice(list(product(range(grid_width), range(grid_height))))
        if can_place(grid, x, y):
            place_piece(grid, x, y)
            placed += 1

    # Count the number of distinct configurations
    configurations = 0
    for x, y in product(range(grid_width), range(grid_height)):
        if grid[x][y] == 1:
            configurations += 1

    # Independent route: enumerate all possible placements and check for distinct configurations
    check = 0
    for x, y in product(range(grid_width), range(grid_height)):
        if grid[x][y] == 1:
            check += 1

    assert configurations == check, f"configurations={configurations} check={check}"

    problem = (
        f"In a {grid_width} by {grid_height} grid, place {pieces} non-overlapping {piece_shape} pieces such that no two pieces share a side. How many distinct configurations are possible? State only the integer."
    )

    return problem, str(configurations)


