import random

def generate(seed):
    rng = random.Random(seed)
    radius = rng.randint(5, 20)
    distance = rng.randint(1, radius - 1)

    # The number of intersection points between a circle and a line is determined by the distance from the center of the circle to the line.
    # If the distance is less than the radius, there are 2 intersection points.
    # If the distance is equal to the radius, there is 1 intersection point.
    # If the distance is greater than the radius, there are 0 intersection points.
    if distance < radius:
        answer = 2
    elif distance == radius:
        answer = 1
    else:
        answer = 0

    # Independent route: check the distance condition for each point on the circle.
    check = 0
    for x in range(-radius, radius + 1):
        for y in range(-radius, radius + 1):
            if x**2 + y**2 == radius**2:
                if abs(x) + abs(y) == distance:
                    check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"A circle has centre O and radius r = {radius}, and a line lies at distance d = {distance} from O, where r and d are positive integers. "
        f"How many points lie on both the circle and the line? State only the integer."
    )

    return problem, str(answer)


