import random
from math import comb, factorial

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(5, 10)
    m = rng.randint(2, n)

    answer = sum(
        comb(n, k) * factorial(k) * factorial(m - 1) * factorial(k - 1)
        for k in range(1, m + 1)
    )

    check = sum(
        sum(1 for _ in permutations(range(n), k)) * factorial(m - 1)
        for k in range(1, m + 1)
    )
    assert answer == check, f"answer={answer} check={check}"

    problem = f"There are {n} distinct books and {m} distinct shelves. In how many ways can the books be arranged on the shelves such that no shelf is empty and each shelf contains at least one book? State only the integer."
    return problem, str(answer)


