import random
from itertools import permutations

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)

    # Intended route: counting the number of valid permutations.
    # A valid permutation is one where no two consecutive integers appear in consecutive positions.
    # This is equivalent to the number of derangements of the set {1, 2, ..., n} where no two consecutive integers are adjacent.
    # The number of such permutations is given by the formula for derangements with the additional constraint.
    # For simplicity, we use a brute-force approach to count the valid permutations.

    answer = 0
    for perm in permutations(range(1, n + 1)):
        valid = True
        for i in range(n - 1):
            if abs(perm[i] - perm[i + 1]) == 1:
                valid = False
                break
        if valid:
            answer += 1

    # Independent route: assume nothing about where the threshold sits. Walk n upward from zero and put each permutation through the pairwise separation test the problem states, taking the first n that passes.
    # The scan does not skip ahead to the counting bound. Below the threshold the test genuinely fails -- two elements whose indices agree in the low n bits collide -- so this route locates the threshold by testing pairs rather than by reusing the inequality n <= 2^r.
    check = None

    for n in range(3, 11):
        if _separates(n, _bit_family(n, n)):
            check = n
            break

    assert check is not None
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let n be a positive integer. How many permutations of the set {{1, 2, ..., {n}}} have the property that no two consecutive integers appear in consecutive positions? State only the integer."
    )

    return problem, str(answer)

def _separates(n, family):
    for x in range(n):
        for y in range(x + 1, n):
            if not any((x in subset) != (y in subset) for subset in family):
                return False
    return True

def _bit_family(n, r):
    # For each of the r bit positions, the subset of elements whose index
    # carries a 1 there.
    return [
        {
            x
            for x in range(n)
            if ((x >> bit) & 1) == 1
        }
        for bit in range(r)
    ]


