def generate(seed):
    rng = random.Random(seed)
    rows = rng.randint(2, 10)
    columns = rng.randint(2, 10)
    forbidden_paths = rng.randint(0, comb(rows + columns - 2, rows - 1))

    # Calculate the total number of paths without any restrictions.
    total_paths = comb(rows + columns - 2, rows - 1)

    # Calculate the number of paths that go through each forbidden path.
    paths_through_forbidden = 0
    for i in range(forbidden_paths):
        # Choose a random forbidden path (a specific cell that the robot must avoid).
        row, col = rng.randint(1, rows - 1), rng.randint(1, columns - 1)
        # Calculate the number of paths that go through this forbidden cell.
        paths_through_cell = comb(row - 1 + col - 1, row - 1) * comb(rows - row + columns - col - 1, rows - row)
        paths_through_forbidden += paths_through_cell

    # Subtract the paths that go through any forbidden path from the total paths.
    answer = total_paths - paths_through_forbidden

    # Check by generating all possible paths and counting the valid ones.
    valid_paths = 0
    for path in generate_all_paths(rows, columns):
        if not path_has_forbidden_cells(path, forbidden_paths):
            valid_paths += 1
    check = valid_paths

    assert answer == check, f"answer={answer} check={check}"

    problem = f"A robot starts at the bottom-left corner of a grid with dimensions {rows} rows by {columns} columns. The robot can move either up or right at each step. However, there are {forbidden_paths} forbidden paths that the robot must avoid. How many valid paths can the robot take to reach the top-right corner? State only the integer."
    return problem, str(answer)

def generate_all_paths(rows, columns):
    # Generate all possible paths using a recursive approach.
    def generate_paths(row, col, path):
        if row == rows and col == columns:
            yield path
        if row < rows:
            yield from generate_paths(row + 1, col, path + "U")
        if col < columns:
            yield from generate_paths(row, col + 1, path + "R")
    return list(generate_paths(0, 0, ""))

def path_has_forbidden_cells(path, forbidden_paths):
    # Check if a path has any forbidden cells.
    forbidden_cells = set()
    for i in range(forbidden_paths):
        row, col = rng.randint(1, rows - 1), rng.randint(1, columns - 1)
        forbidden_cells.add((row, col))
    for cell in forbidden_cells:
        if cell in path:
            return True
    return False


