    n = rng.randint(5, 15)
    k = rng.randint(1, n // 2)

    # The number of ways to partition a set of n elements into subsets of size k is given by the multinomial coefficient.
    # However, since the subsets are indistinct, we need to divide by the factorial of the number of subsets.
    # The number of subsets is n // k.
    answer = comb(n, k) // (comb(n // k, 1) ** (n // k))

    # Check by generating all possible partitions and counting the valid ones.
