    rng = random.Random(seed)
    grid_size = 3

    def is_valid_tiling(tiling):
        grid = [[0] * grid_size for _ in range(grid_size)]
        for (x1, y1), (x2, y2) in tiling:
            if x1 == x2:
                for y in range(min(y1, y2), max(y1, y2) + 1):
                    if grid[x1][y] != 0:
                        return False
                    grid[x1][y] = 1
            else:
                for x in range(min(x1, x2), max(x1, x2) + 1):
                    if grid[x][y1] != 0:
                        return False
                    grid[x][y1] = 1
        return all(all(cell == 0 for cell in row) for row in grid)

    def generate_tiling():
        for tiling in product([(0, 0), (0, 1), (0, 2), (1, 0), (1, 1), (1, 2), (2, 0), (2, 1), (2, 2)], repeat=2):
            if is_valid_tiling(tiling):
                return tiling
        return None

    tiling = generate_tiling()
    if tiling is None:
        return "No valid tiling found", "0"

    answer = 1  # There is exactly one valid tiling for a 3x3 grid with dominoes

    check = sum(1 for _ in product([(0, 0), (0, 1), (0, 2), (1, 0), (1, 1), (1, 2), (2, 0), (2, 1), (2, 2)], repeat=2) if is_valid_tiling(_))
    assert answer == check, f"answer={answer} check={check}"

    problem = f"Consider a 3 by 3 grid. How many ways can you tile the grid using 1x2 dominoes and 2x1 dominoes, ensuring that every cell is covered exactly once? State only the integer."
    return problem, str(answer)


