    check[0] = 1
    for i in range(1, board_length + 1):
        check[i] = check[i - 1] + (check[i - 2] if i >= 2 else 0)

    assert answer == check[board_length], f"answer={answer} check={check[board_length]}"

    problem = (
        f"Let N = {board_length} be a positive integer. In how many ways can a 1xN board be tiled with 1x1 and 1x2 tiles? State only the integer."
