import random
from collections import deque

def generate(seed):
    rng = random.Random(seed)
    n = 8

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def knight_moves(x, y):
        return [
            (x + 2, y + 1), (x + 2, y - 1),
            (x - 2, y + 1), (x - 2, y - 1),
            (x + 1, y + 2), (x + 1, y - 2),
            (x - 1, y + 2), (x - 1, y - 2)
        ]

    start = (0, 0)
    visited = set()
    queue = deque([start])

    for _ in range(3):
        new_queue = deque()
        while queue:
            x, y = queue.popleft()
            for nx, ny in knight_moves(x, y):
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    new_queue.append((nx, ny))
        queue = new_queue

    answer = len(visited)

    check = 0
    for x in range(n):
        for y in range(n):
            if (x, y) in visited:
                check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = f"On an 8x8 chessboard, a knight starts at the bottom-left corner. How many distinct squares can the knight reach after exactly 3 moves? State only the integer."
    return problem, str(answer)


