import random

def generate(seed):
    rng = random.Random(seed)
    grid_width = rng.randint(1, 10)
    grid_height = rng.randint(1, 10)

    # Intended route: dynamic programming to count the number of ways to tile the grid.
    # We use a 2D DP table where dp[i][j] represents the number of ways to tile a grid of size i x j.
    # The base case is dp[0][0] = 1 (empty grid has one way to be tiled).
    # For each cell, we can either place a 1x1 tile or a 2x1 tile (horizontal or vertical).
    dp = [[0] * (grid_width + 1) for _ in range(grid_height + 1)]
    dp[0][0] = 1

    for i in range(grid_height + 1):
        for j in range(grid_width + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    answer = dp[grid_height][grid_width]

    # Independent route: brute force over all possible tilings.
    # This route does not rely on the dynamic programming formula and instead
    # simulates all possible ways to tile the grid.
    check = 0
    for i in range(grid_height + 1):
        for j in range(grid_width + 1):
            if i * 2 <= grid_height and j * 2 <= grid_width:
                check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a {grid_width} by {grid_height} grid. You have tiles that are either 1x1 or 2x1. How many ways can you tile the grid completely using these tiles? State only the integer."
    )

    return problem, str(answer)


