import random
from itertools import combinations

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)

    # The problem is to count the number of ways to color the edges of a complete graph
    # with n vertices such that no monochromatic triangle exists. This is equivalent to
    # counting the number of 2-colorings of the edges of the complete graph that avoid
    # monochromatic triangles.

    # The number of such colorings is given by the Ramsey number R(3, 3), which is 6.
    # For n >= 6, the number of valid colorings is 2^(n choose 2) / 2^(n-1) = 2^(n(n-1)/2 - (n-1)).
    # For n < 6, the number of valid colorings is 2^(n choose 2).

    if n < 6:
        answer = 2 ** (n * (n - 1) // 2)
    else:
        answer = 2 ** (n * (n - 1) // 2 - (n - 1))

    # Independent route: enumerate all possible colorings and count those without monochromatic triangles.
    check = 0
    for coloring in combinations(range(n * (n - 1) // 2), n * (n - 1) // 2):
        edges = set(coloring)
        valid = True
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if (i, j) in edges and (j, k) in edges and (k, i) in edges:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break
        if valid:
            check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a complete graph with {n} vertices. Each edge can be colored either red or blue. "
        f"How many ways are there to color the graph such that no monochromatic triangle exists? "
        f"State only the integer."
    )

    return problem, str(answer)


