import random
from math import ceil, log2


def _separates(n, family):
    for x in range(n):
        for y in range(x + 1, n):
            if not any((x in subset) != (y in subset) for subset in family):
                return False
    return True


def _bit_family(n, r):
    return [
        {
            x
            for x in range(n)
            if ((x >> bit) & 1) == 1
        }
        for bit in range(r)
    ]


def generate(seed):
    rng = random.Random(seed)

    width = rng.randint(3, 10)
    n = rng.randint((1 << (width - 1)) + 1, 1 << width)

    answer = ceil(log2(n))

    check = None
    for r in range(n + 1):
        if _separates(n, _bit_family(n, r)):
            check = r
            break

    assert check is not None
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let S be a set of {n} elements. Find the minimum number of subsets of S needed to ensure that every pair of distinct elements is contained in at least one subset. State only the integer."
    )

    return problem, str(answer)


