        f"In how many ways can n distinct points be partitioned into subsets of size k = {subset_size}? "
        f"State only the integer."
    )

    return problem, str(answer)

def partitions(n, k):
    if n == 0:
        yield []
    elif n < k:
        yield []
    else:
        for i in range(1, n // k + 1):
            for p in partitions(n - i * k, k):
                yield [i] + p


