    n = rng.randint(5, 15)
    k = rng.randint(2, 5)

    # The number of ways to distribute n indistinguishable balls into k distinguishable bins such that no bin is empty is given by the Stirling number of the second kind, S(n, k), multiplied by k!.
    # The Stirling number of the second kind, S(n, k), is the number of ways to partition a set of n objects into k non-empty subsets.
    # The formula for S(n, k) is: S(n, k) = k * S(n-1, k) + S(n-1, k-1)
    # We can compute S(n, k) using dynamic programming.

    def stirling(n, k):
        if n == 0 and k == 0:
            return 1
        if n == 0 or k == 0:
            return 0
        return k * stirling(n - 1, k) + stirling(n - 1, k - 1)

    answer = stirling(n, k) * comb(n - 1, k - 1)

    # Independent route: enumerate the distributions and count the valid ones.
    check = 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i + j - 1 == n:
                check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"There are {n} indistinguishable balls and {k} distinguishable bins. In how many ways can the balls be distributed into the bins such that no bin is empty? State only the integer."
