    rng = random.Random(seed)
    n = rng.randint(3, 10)

    # The number of ways to color the edges of a complete graph K_n such that no triangle has all three edges the same color
    # is given by the Ramsey number R(3, 3) = 6. For n < 6, the number of valid colorings is 2^(n choose 2).
    # For n >= 6, the number of valid colorings is 0.
    if n < 6:
        answer = 2 ** (n * (n - 1) // 2)
    else:
        answer = 0

    # Check by brute force over all possible colorings of the edges
    check = 0
    for coloring in range(2 ** (n * (n - 1) // 2)):
        edges = [(i, j) for i in range(n) for j in range(i + 1, n)]
        color = [int((coloring >> (i * (i - 1) // 2 + j - (i * (i - 1) // 2))) & 1) for i, j in edges]
        valid = True
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if color[edges.index((i, j))] == color[edges.index((j, k))] == color[edges.index((k, i))]:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break
        if valid:
            check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider a complete graph \( K_n \) with \( n \) vertices, where each edge is colored either red or blue. "
        f"How many ways can the edges be colored such that no triangle has all three edges the same color? "
        f"State only the integer."
    )

    return problem, str(answer)


