import random
from math import comb, factorial

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(5, 15)
    k = rng.randint(1, n)

    # The number of ways to partition a set of n elements into k non-empty subsets
    # is given by the Stirling numbers of the second kind, S(n, k), multiplied by k!.
    # The Stirling number S(n, k) can be computed using the formula:
    # S(n, k) = k * S(n-1, k) + S(n-1, k-1)
    # with base cases S(0, 0) = 1 and S(n, 0) = S(0, n) = 0 for n > 0.

    def stirling(n, k):
        if n == 0 and k == 0:
            return 1
        if n == 0 or k == 0:
            return 0
        return k * stirling(n - 1, k) + stirling(n - 1, k - 1)

    answer = stirling(n, k) * factorial(k)

    # Independent route: enumerate all possible partitions and count the valid ones.
    # This is computationally expensive for large n and k, so it's only used for verification.
    check = 0
    elements = list(range(1, n + 1))
    subsets = []

    def backtrack(start, current_subset):
        if len(current_subset) == k:
            subsets.append(current_subset)
            return
        for i in range(start, n):
            backtrack(i + 1, current_subset + [elements[i]])

    backtrack(0, [])
    for subset in subsets:
        if len(subset) == k:
            check += 1

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"A set contains {n} distinct elements. How many ways can you partition this set into {k} non-empty subsets? State only the integer."
    )

    return problem, str(answer)


