def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(1, 10)

    # Intended route: Dynamic programming to count the number of ways the knight can reach the top-right corner of a 2 by n chessboard.
    # The knight can move to any of the squares that are two squares in one direction and one square in a perpendicular direction.
    # We use a dynamic programming approach to count the number of ways the knight can reach each square.
    dp = [[0] * n for _ in range(2)]
    dp[0][0] = 1

    for i in range(2):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if i == 0:
                dp[i][j] = dp[i][j - 1]
            elif i == 1:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j + 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j + 1]

    answer = dp[1][n - 1]

    # Independent route: Recursive approach to count the number of ways the knight can reach the top-right corner of a 2 by n chessboard.
    # This route does not rely on the dynamic programming approach and instead uses recursion to count the number of ways.
    def count_ways(i, j):
        if i == 1 and j == n - 1:
            return 1
        if i < 0 or j < 0 or i >= 2 or j >= n:
            return 0
        return count_ways(i - 1, j - 1) + count_ways(i - 1, j + 1)

    check = count_ways(0, 0)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"A knight starts at the bottom-left corner of a 2 by {n} chessboard. It can move to any of the squares that are two squares in one direction and one square in a perpendicular direction. How many ways can the knight reach the top-right corner of the board? State only the integer."
    )

    return problem, str(answer)


