import random
from itertools import permutations

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 7)

    # Intended route: Derangement formula. The number of derangements (permutations where no element appears in its original position) of n items is given by the formula:
    # !n = n! * (1 - 1/1! + 1/2! - 1/3! + ... + (-1)^n / n!)
    def factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return n * factorial(n - 1)

    def derangement(n):
        if n == 0:
            return 1
        elif n == 1:
            return 0
        else:
            return (n - 1) * (derangement(n - 1) + derangement(n - 2))

    answer = derangement(n)

    # Independent route: Counting derangements using permutations.
    # This route does not rely on the derangement formula and instead uses permutations to count the number of derangements.
    check = sum(
        all(p[i] != i for i in range(n))
        for p in permutations(range(n))
    )

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"There are {n} distinct items and {n} distinct positions. How many ways can the items be assigned to the positions such that no item is assigned to its own position? State only the integer."
